import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import './Login.css';

const USER_TYPES = [
  { value: 'admin', label: 'Admin', icon: '⬡', desc: 'Accès complet' },
  { value: 'agent', label: 'Agent', icon: '◈', desc: 'Check-in / Check-out' },
  { value: 'host', label: 'Hôte', icon: '◇', desc: 'Gestion invités' },
  { value: 'visitor', label: 'Visiteur', icon: '○', desc: 'Suivi visites' },
];

export default function Login() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: '', password: '', userType: 'admin' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await login(form.email, form.password, form.userType);
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.message || 'Identifiants incorrects');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-root">
      <div className="login-left">
        <div className="login-brand">
          <div className="login-badge">ENS</div>
          <h1>École Normale<br />Supérieure</h1>
          <p>Marrakech — Système de gestion des visiteurs du campus</p>
        </div>
        <div className="login-deco">
          <div className="deco-ring r1" />
          <div className="deco-ring r2" />
          <div className="deco-ring r3" />
        </div>
      </div>

      <div className="login-right">
        <form className="login-card" onSubmit={handleSubmit}>
          <h2>Connexion</h2>
          <p className="login-hint">Choisissez votre profil d'accès</p>

          <div className="user-type-grid">
            {USER_TYPES.map(t => (
              <button
                key={t.value}
                type="button"
                className={`type-btn ${form.userType === t.value ? 'active' : ''}`}
                onClick={() => setForm(f => ({ ...f, userType: t.value }))}
              >
                <span className="type-icon">{t.icon}</span>
                <span className="type-label">{t.label}</span>
                <span className="type-desc">{t.desc}</span>
              </button>
            ))}
          </div>

          <div className="field">
            <label>Email</label>
            <input
              type="email"
              placeholder="votre@email.com"
              value={form.email}
              onChange={e => setForm(f => ({ ...f, email: e.target.value }))}
              required
            />
          </div>

          <div className="field">
            <label>Mot de passe</label>
            <input
              type="password"
              placeholder="••••••••"
              value={form.password}
              onChange={e => setForm(f => ({ ...f, password: e.target.value }))}
              required
            />
          </div>

          {error && <div className="login-error">{error}</div>}

          <button className="login-btn" type="submit" disabled={loading}>
            {loading ? 'Connexion...' : 'Se connecter'}
          </button>
          <p style={{ textAlign:'center', marginTop:16, fontSize:13, color:'var(--muted)' }}>
  <Link to="/forgot-password" style={{ color:'var(--text)', textDecoration:'none' }}>
    Mot de passe oublié ?
  </Link>
</p>
        </form>
      </div>
    </div>
  );
}
